    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _val, uint _val2, bool doInit) public {
        uint beforeMinSum = c.MinSum();

        bool firstReverted;
        try c.SetMinSum(_val) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool initReverted;
        if (doInit) {
            try c.Initialized() {
                initReverted = false;
            } catch {
                initReverted = true;
            }
        } else {
            initReverted = false;
        }

        uint midMinSum = c.MinSum();

        bool secondReverted;
        try c.SetMinSum(_val2) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint afterMinSum = c.MinSum();

        if (!doInit) {
            assert(
                !firstReverted &&
                midMinSum == _val &&
                !secondReverted &&
                afterMinSum == _val2 &&
                beforeMinSum == 0
            );
        } else {
            assert(
                !firstReverted &&
                midMinSum == _val &&
                !initReverted &&
                secondReverted &&
                afterMinSum == _val
            );
        }
    }
}

