contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address _log, uint _markInit) public payable {
        // Drive c to the uninitialized state explicitly (fresh deployment already is,
        // but call SetLogFile once to be sure, then mark initialized if requested).
        bool revertedBefore = false;
        try c.SetLogFile(_log) { revertedBefore = false; } catch { revertedBefore = true; }

        if (_markInit != 0) {
            c.Initialized();
        }

        bool revertedAfter;
        try c.SetLogFile(_log) { revertedAfter = false; } catch { revertedAfter = true; }

        // General rule: on a fresh/uninitialized contract SetLogFile succeeds;
        // once Initialized() has been called it always reverts.
        if (_markInit == 0) {
            assert(!revertedBefore && !revertedAfter);
        } else {
            assert(!revertedBefore && revertedAfter);
        }
    }

    receive() external payable {}
}

